SELECT /* FDA READ */ /* CDS access control applied */ "COMPANYCODE" , "ACCOUNTINGDOCUMENT" , "FISCALYEAR" , "ACCOUNTINGDOCUMENTITEM", y_awtyp, y_awkey FROM /* CDS access controlled */ "ZHGI_ARLINEITEM" ( "P_KEYDATE" => '20230101' , "P_TODAYDATE" => '20230101' , "P_LANGUAGE" => 'E' , "P_DISPUTECASEACCESSISGRANTED" => NULL , "P_TIMERESTRICTIONSTARTDATE" => '00000000' ) WHERE "MANDT" = '720' and y_awkey = '01001246521010' and SelectedItemBranch in ('BSEG_CREDIT_SIDE_BRANCH','BSEG_DEBIT_SIDE_BRANCH') ORDER BY "COMPANYCODE" , "ACCOUNTINGDOCUMENT" , "FISCALYEAR" , "ACCOUNTINGDOCUMENTITEM" LIMIT 200 WITH HINT(ignore_plan_cache, NO_SELF_JOIN_REMOVAL_WITH_SQL_PARAMETERS);
